<script lang="ts">
 import {onMount} from 'svelte';
 import {localization} from '#lib/localization.js';
 import type {Project,Ticket} from '#lib/projects.js';
 import {canOperate} from '#lib/auth.js';
 import {readSessionUser} from '#lib/client-session.js';
 import PageTabs from '#lib/components/PageTabs.svelte';
 import ActionButton from '#lib/components/ActionButton.svelte';
 import StatusNotice from '#lib/components/StatusNotice.svelte';
 import SearchSelect from '#lib/components/SearchSelect.svelte';
 import SearchMultiSelect from '#lib/components/SearchMultiSelect.svelte';
 import DatePicker from '#lib/components/DatePicker.svelte';
 import FormInput from '#lib/components/FormInput.svelte';
 import FormTextarea from '#lib/components/FormTextarea.svelte';
 import FormSection from '#lib/components/FormSection.svelte';
 import DetailModal from '#lib/components/DetailModal.svelte';
 import InfoPopover from '#lib/components/InfoPopover.svelte';
 import ManagementForm,{type Field} from './ManagementForm.svelte';
 import ManagementChart from './ManagementChart.svelte';
 let {project}:{project:Project}=$props();
 type Settings={id:number;revision:number;enabled:boolean;currency:'JPY'|'USD';startMonth:string};
 type Rate={id:number;revision:number;startsOn:string;hourlyRate:string};
 type Expense={id:number;revision:number;code:string;ticketId:number;incurredOn:string;amount:string;category:string;evidence:string};
 type PlanItem={ticketId:number;title:string;budget:string;ProjectBaselineMonth_itemId:Array<{month:string;amount:string}>};
 type Baseline={id:number;version:number;title:string;reason:string;state:string;ProjectBaselineItem_baselineId:PlanItem[]};
 type Totals={currency:string;bac:string;pv:string;ev:string;ac:string;cv:string;sv:string;cpi:string|null;spi:string|null;eac:string|null;vac:string|null};
 type ReportData={baselineId:number;baselineVersion:number;month:string;currency:string;totals:Totals|null;unresolved:string[];rows:Array<{ticketId:number;title:string;budget:string;planned:string;progress:string;actual:string}>;evidence:unknown[]};
 type Report={id:number;baselineId:number;month:string;version:number;stale:boolean;snapshot:ReportData};
 type Progress={id:number;ticketId:number;month:string;version:number;percent:string;evidence:string};
 let staleDismissed=$state(false);
 let settings=$state<Settings|null>(null),rates=$state<Rate[]>([]),expenses=$state<Expense[]>([]),baselines=$state<Baseline[]>([]),reports=$state<Report[]>([]),progress=$state<Progress[]>([]),tickets=$state<Ticket[]>([]),operations=$state<string[]>([]),loading=$state(true),busy=$state(false),error=$state(''),notice=$state(''),tab=$state('dashboard'),baseline=$state('');
 let monthOpen=$state(false),calculating=$state(false),previewError=$state(''),dataRevision=$state(0);
 let reportMonth=$state(new Date(Date.UTC(new Date().getFullYear(),new Date().getMonth()-1,1)).toISOString().slice(0,7)),preview=$state<ReportData|null>(null);
 let editor=$state<{title:string;fields:Field[];save:(v:Record<string,string|string[]>)=>Promise<void>}|null>(null);
 let baselineOpen=$state(false),baselineTitle=$state(''),baselineReason=$state(''),baselineState=$state('draft'),workIds=$state<string[]>([]),budgets=$state<Record<string,string>>({}),allocations=$state<Record<string,string>>({}),months=$state<string[]>([]),baselineError=$state('');
 const tr=(j:string,e:string)=>$localization.displayLanguage==='ja'?j:e;
 const path=()=>'/v1/projects/'+project.id;
 const can=(op:string)=>operations.includes(op);
 const manage=()=>can('projects.financial.manage')&&project.role==='manager'&&project.status!=='archived';
 const field=(key:string,label:string,kind:Field['kind']='text',value:string|string[]=''):Field=>({key,label,kind,value,required:true});
 const optTickets=()=>tickets.map(t=>({value:String(t.id),label:t.code+' · '+t.title}));
 const amount=(value:string|null|undefined)=>value===null||value===undefined?'—':new Intl.NumberFormat($localization.displayLanguage,{style:'currency',currency:settings?.currency??'JPY',maximumFractionDigits:settings?.currency==='USD'?2:0}).format(Number(value));
 async function api<T>(suffix:string,method='GET',body?:unknown,signal?:AbortSignal):Promise<T>{const r=await fetch(path()+'/'+suffix,{method,signal,headers:{'content-type':'application/json'},...(body===undefined?{}:{body:JSON.stringify(body)})});const p=await r.json();if(!r.ok)throw Error(tr('操作できませんでした。入力・権限・競合を確認してください。','Request failed. Check input, permissions and conflicts.')+' ['+(p.error?.code??r.status)+']');return p.data;}
 async function load(){const user=await readSessionUser();operations=['projects.financial.read','projects.financial.manage','projects.baselines.confirm','projects.evm.confirm'].filter(op=>canOperate(user,op));[settings,rates,expenses,baselines,reports,progress]=await Promise.all([api<Settings|null>('evm-settings'),api<Rate[]>('cost-rates?limit=500'),api<Expense[]>('expenses?limit=500'),api<Baseline[]>('baselines?limit=500'),api<Report[]>('evm-reports?limit=500'),api<Progress[]>('progress-records?limit=500')]);if(!baselines.some(b=>String(b.id)===baseline&&b.state==='confirmed'))baseline=String(baselines.find(b=>b.state==='confirmed')?.id??'');tickets=[];for(let offset=0;;offset+=500){const r=await fetch(path()+'/tickets?limit=500&offset='+offset),body=await r.json();if(!r.ok)throw Error('PROJECT_READ_FAILED');const rows=body.data as Ticket[];tickets.push(...rows);if(rows.length<500)break;}preview=null;dataRevision++;}
 onMount(()=>{void load().catch(e=>error=e.message).finally(()=>loading=false);});
 const saved=async(suffix:string,method:string,body:unknown)=>{await api(suffix,method,body);await load();notice=tr('保存しました。確定済み報告への影響も確認してください。','Saved. Review any impact on confirmed reports.');};
 function configure(){editor={title:tr('EVMの設定','EVM settings'),fields:[{...field('enabled',tr('EVM管理','EVM management'),'select',String(settings?.enabled??true)),options:[{value:'true',label:tr('有効','Enabled')},{value:'false',label:tr('無効','Disabled')}]},field('startMonth',tr('管理開始月','Management start month'),'month',settings?.startMonth.slice(0,7)??reportMonth),{...field('currency',tr('管理通貨・税抜','Currency · tax exclusive'),'select',settings?.currency??'JPY'),options:[{value:'JPY',label:'JPY'},{value:'USD',label:'USD'}]}],save:v=>saved('evm-settings','PATCH',{enabled:v.enabled==='true',startMonth:v.startMonth,currency:v.currency,...(settings?{revision:settings.revision}:{})})};}
 function rateEditor(r?:Rate){editor={title:tr('標準時間単価','Standard hourly rate'),fields:[field('startsOn',tr('適用開始日','Effective date'),'date',r?.startsOn.slice(0,10)??settings?.startMonth.slice(0,10)),field('hourlyRate',tr('1時間の単価・税抜','Hourly rate · tax exclusive'),'number',r?.hourlyRate??'0')],save:v=>saved('cost-rates'+(r?'/'+r.id:''),r?'PATCH':'POST',{...v,...(r?{revision:r.revision}:{})})};}
 function expenseEditor(e?:Expense){editor={title:tr('経費明細・税抜','Expense · tax exclusive'),fields:[field('code',tr('明細番号','Expense code'),'text',e?.code),{...field('ticketId',tr('対象チケット','Ticket'),'select',e?String(e.ticketId):''),options:optTickets()},field('incurredOn',tr('計上日','Incurred date'),'date',e?.incurredOn.slice(0,10)??reportMonth+'-01'),field('amount',tr('金額・税抜','Amount · tax exclusive'),'number',e?.amount),field('category',tr('費目','Category'),'text',e?.category),field('evidence',tr('根拠・確認内容','Evidence'),'textarea',e?.evidence)],save:v=>saved('expenses'+(e?'/'+e.id:''),e?'PATCH':'POST',{...v,ticketId:Number(v.ticketId),...(e?{revision:e.revision}:{})})};}
 function progressEditor(ticketId?:number){const items=baselines.find(b=>String(b.id)===baseline)?.ProjectBaselineItem_baselineId??[];editor={title:tr('月次進捗と根拠','Monthly progress and evidence'),fields:[{...field('ticketId',tr('作業単位','Work package'),'select',ticketId?String(ticketId):''),options:items.map(i=>({value:String(i.ticketId),label:i.title}))},field('month',tr('対象月','Status month'),'month',reportMonth),field('percent',tr('累積進捗率（0〜100%）','Cumulative progress (0–100%)'),'number','0'),field('evidence',tr('進捗判定の根拠','Progress evidence'),'textarea')],save:v=>saved('progress-records','POST',{...v,ticketId:Number(v.ticketId)})};}
 $effect(()=>{
  const selectedBaseline=baseline,selectedMonth=reportMonth;dataRevision;
  preview=null;previewError='';
  if(loading||!settings?.enabled||!selectedBaseline){calculating=false;return;}
  const controller=new AbortController();let current=true;calculating=true;
  void api<ReportData>('evm-preview?baselineId='+selectedBaseline+'&month='+selectedMonth,'GET',undefined,controller.signal)
   .then(result=>{if(current)preview=result;})
   .catch(e=>{if(current)previewError=(e as Error).message;})
   .finally(()=>{if(current)calculating=false;});
  return()=>{current=false;controller.abort();};
 });
 async function confirmReport(){if(calculating||previewError||preview?.baselineId!==Number(baseline)||preview?.month.slice(0,7)!==reportMonth||!preview?.totals||!confirm(tr('工数・経費・進捗を確認し、この月の報告を確定しますか？ 訂正時も元の版は保持されます。','Confirm that time, expenses and progress are complete and publish this month? Previous versions remain available after corrections.')))return;busy=true;error='';try{const prior=reports.filter(r=>r.month.slice(0,7)===reportMonth).sort((a,b)=>b.version-a.version)[0];await saved('evm-reports','POST',{baselineId:Number(baseline),month:reportMonth,revision:prior?.version??0});}catch(e){error=(e as Error).message;}finally{busy=false;}}
 function openBaseline(b?:Baseline){baselineTitle=b?.title??tr('基準計画','Baseline');baselineReason='';baselineState='draft';workIds=b?.ProjectBaselineItem_baselineId.map(i=>String(i.ticketId))??[];budgets={};allocations={};for(const i of b?.ProjectBaselineItem_baselineId??[]){budgets[i.ticketId]=i.budget;for(const m of i.ProjectBaselineMonth_itemId)allocations[i.ticketId+':'+m.month.slice(0,7)]=m.amount;}const existing=b?.ProjectBaselineItem_baselineId.flatMap(i=>i.ProjectBaselineMonth_itemId.map(m=>m.month.slice(0,7)))??[];months=existing.length?[...new Set(existing)].sort():[settings!.startMonth.slice(0,7)];baselineError='';baselineOpen=true;}
 function appendMonth(){const d=new Date(months.at(-1)+'-01T00:00:00Z');d.setUTCMonth(d.getUTCMonth()+1);months=[...months,d.toISOString().slice(0,7)];}
 async function saveBaseline(){busy=true;baselineError='';try{await saved('baselines','POST',{title:baselineTitle,reason:baselineReason,state:baselineState,revision:Math.max(0,...baselines.map(b=>b.version)),items:workIds.map(id=>({ticketId:Number(id),budget:budgets[id]??'0',months:months.map(m=>({month:m,amount:allocations[id+':'+m]??'0'}))}))});baselineOpen=false;}catch(e){baselineError=(e as Error).message;}finally{busy=false;}}
 let chosen=$derived(baselines.find(b=>String(b.id)===baseline));
 let latestReports=$derived([...new Map([...reports].sort((a,b)=>a.version-b.version).filter(r=>String(r.baselineId)===baseline).map(r=>[r.month.slice(0,7),r])).values()].sort((a,b)=>a.month.localeCompare(b.month)));
 function plannedMoney(month:string){const values=(chosen?.ProjectBaselineItem_baselineId??[]).flatMap(i=>i.ProjectBaselineMonth_itemId).filter(p=>p.month.slice(0,7)<=month).map(p=>p.amount);const cents=values.reduce((sum,v)=>{const [whole,fraction='']=v.split('.');return sum+BigInt(whole)*100n+BigInt(fraction.padEnd(2,'0'));},0n);return (cents/100n).toString()+'.'+(cents%100n).toString().padStart(2,'0');}
 let chartMonths=$derived([...new Set([...(chosen?.ProjectBaselineItem_baselineId.flatMap(i=>i.ProjectBaselineMonth_itemId.map(m=>m.month.slice(0,7)))??[]),...latestReports.map(r=>r.month.slice(0,7))])].sort());
 let totals=$derived(preview?.totals??null);
 const unresolvedLabel=(code:string)=>({MISSING_RATE:tr('標準単価が未設定','Missing hourly rate'),UNMAPPED_TIME:tr('基準計画の範囲外の工数','Time outside baseline scope'),UNMAPPED_EXPENSE:tr('基準計画の範囲外の経費','Expense outside baseline scope'),MISSING_MONTHLY_PROGRESS:tr('月次進捗の確認が未完了','Monthly progress missing')}[code]??code);
</script>
<div class="evm" data-evm-dashboard>
{#if error}<StatusNotice tone="error" message={error} onDismiss={()=>error=''}/>{/if}{#if notice}<StatusNotice tone="success" message={notice} onDismiss={()=>notice=''}/>{/if}
{#if loading}<p>{tr('読み込み中…','Loading…')}</p>{:else}
<header class="heading"><div><h2>{tr('実行管理：EVM','Execution management: EVM')}</h2><p>{tr('予算・出来高・原価を月次で管理します。','Manage budget, earned value and actual costs monthly.')}</p></div>{#if manage()}<ActionButton label={tr('EVM設定','EVM settings')} onclick={configure}/>{/if}</header>
{#if !settings?.enabled}<section class="empty">{tr('EVMは無効です。管理開始月・通貨を設定し、対象作業の基準計画を作成してください。開始前の実績は自動計上しません。','EVM is disabled. Set a start month and currency, then create the baseline scope. Earlier actuals are not inferred.')}</section>{:else}
<div class="controls"><SearchSelect label={tr('確定した基準計画','Confirmed baseline')} field="evm-baseline" value={baseline} options={baselines.filter(b=>b.state==='confirmed').map(b=>({value:String(b.id),label:'v'+b.version+' · '+b.title}))} onSelect={v=>baseline=v}/><DatePicker label={tr('対象月','Status month')} field="evm-month" value={reportMonth} mode="month" open={monthOpen} onToggle={()=>monthOpen=!monthOpen} onSelect={v=>{reportMonth=v;monthOpen=false;}}/><div class="calculation-info"><span>{settings.currency} · {tr('税抜','Tax exclusive')}</span><span role="status">{calculating?tr('更新中…','Updating…'):previewError?tr('更新に失敗しました','Update failed'):preview?tr('自動更新済み','Updated automatically'):''}</span></div></div>
{#if reports.some(r=>r.stale)&&!staleDismissed}<StatusNotice onDismiss={()=>staleDismissed=true} tone="info" message={tr('訂正の影響で要再確定の報告があります。元の確定値は保持されています。','Some reports require reconfirmation following corrections. Their original values are retained.')} />{/if}
{#if previewError}<StatusNotice tone="error" message={previewError} onDismiss={()=>previewError=''}/>{/if}
<div class="metrics">{#each [['BAC',tr('総予算','Total budget')],['EV',tr('出来高','Earned value')],['AC',tr('実績原価','Actual cost')],['EAC',tr('完成時予測原価','Forecast cost')]] as [key,label]}<section><small>{label} · {key}</small><strong>{amount(totals?.[key.toLowerCase() as keyof Totals])}</strong></section>{/each}</div>
<PageTabs bottomSpacing={false} idPrefix="evm-view" label={tr('EVM表示','EVM views')} bind:active={tab} tabs={[{id:'dashboard',label:tr('推移・差異','Trends and variance')},{id:'baseline',label:tr('基準計画','Baselines')},{id:'actual',label:tr('原価・進捗','Costs and progress')},{id:'reports',label:tr('月次報告','Monthly reports')}]}/>
{#if tab==='dashboard'}
<ManagementChart title={tr('計画・出来高・実績原価の累積推移','Cumulative planned value, earned value and actual cost')} unit={settings.currency} labels={chartMonths} series={[{name:'PV',color:'var(--action-primary)',dashed:true,values:chartMonths.map(m=>plannedMoney(m))},{name:'EV',color:'#16a34a',values:chartMonths.map(m=>latestReports.find(r=>r.month.slice(0,7)===m)?.snapshot.totals?.ev??null)},{name:'AC',color:'#ea580c',values:chartMonths.map(m=>latestReports.find(r=>r.month.slice(0,7)===m)?.snapshot.totals?.ac??null)}]}/>
{#if totals}<div class="indices">{#each ['cv','sv','cpi','spi','vac'] as key}<div><strong>{key.toUpperCase()}</strong><span class:negative={totals[key as keyof Totals]!==null&&Number(totals[key as keyof Totals])<(key==='cpi'||key==='spi'?1:0)}>{key==='cpi'||key==='spi'?totals[key as 'cpi'|'spi']===null?'—':Number(totals[key as 'cpi'|'spi']).toFixed(2):amount(totals[key as 'cv'|'sv'|'vac'])}</span></div>{/each}</div>{/if}
<InfoPopover label={tr('指標の見方','Understanding the indicators')}><p>{tr('CV=EV−AC、SV=EV−PV、CPI=EV÷AC、SPI=EV÷PV。SVは金額の差異であり遅延日数ではありません。EAC=BAC÷CPIは現在の効率が続く場合の参考見通しです。分母が0なら未算定です。','CV=EV−AC; SV=EV−PV; CPI=EV÷AC; SPI=EV÷PV. SV is a monetary variance, not days late. EAC=BAC÷CPI assumes current cost efficiency continues. Zero denominators are not evaluated.')}</p></InfoPopover>
{#if preview}<h3>{tr('作業別差異','Work-package variance')}</h3>{#each preview.rows as row}<div class="variance"><span>{row.title}</span><div class="variance-track"><span class:negative={Number(row.actual)>Number(row.budget)} style:width={Math.min(100,Number(row.actual)/Math.max(1,Number(row.budget))*100)+'%'}></span></div><span>{amount(row.actual)} / {amount(row.budget)}</span></div>{/each}{/if}
{:else if tab==='baseline'}
{#if manage()}<ActionButton label={tr('基準計画を作成','Create baseline')} variant="primary" onclick={()=>openBaseline()}/>{/if}
{#each baselines as b}<section class="card"><header><h3>v{b.version} · {b.title}</h3><span>{b.state==='confirmed'?tr('確定','Confirmed'):tr('下書き','Draft')}</span></header><p>{b.reason}</p><div class="table-scroll"><table><thead><tr><th>{tr('作業','Work')}</th><th>{tr('予算・税抜','Budget · tax exclusive')}</th><th>{tr('月別配賦','Monthly allocation')}</th></tr></thead><tbody>{#each b.ProjectBaselineItem_baselineId as i}<tr><th>{i.title}</th><td>{amount(i.budget)}</td><td>{i.ProjectBaselineMonth_itemId.map(m=>m.month.slice(0,7)+': '+amount(m.amount)).join(' / ')}</td></tr>{/each}</tbody></table></div>{#if manage()}<ActionButton label={tr('この版を基に改訂・確定','Revise / confirm from this version')} onclick={()=>openBaseline(b)}/>{/if}</section>{/each}
{:else if tab==='actual'}
<section class="card"><header><h3>{tr('標準時間単価','Standard hourly rates')}</h3>{#if manage()}<ActionButton label={tr('単価を追加','Add rate')} onclick={()=>rateEditor()}/>{/if}</header>{#each rates as r}<div class="list-row"><span>{r.startsOn.slice(0,10)}</span><strong>{amount(r.hourlyRate)} / h</strong>{#if manage()}<ActionButton label={tr('編集','Edit')} onclick={()=>rateEditor(r)}/>{/if}</div>{/each}</section>
<section class="card"><header><h3>{tr('経費・税抜','Expenses · tax exclusive')}</h3>{#if manage()}<ActionButton label={tr('経費を追加','Add expense')} onclick={()=>expenseEditor()}/>{/if}</header>{#each expenses as e}<div class="list-row"><span>{e.incurredOn.slice(0,10)} · {e.code} · {e.category}</span><strong>{amount(e.amount)}</strong>{#if manage()}<ActionButton label={tr('編集','Edit')} onclick={()=>expenseEditor(e)}/>{/if}</div>{/each}</section>
<section class="card"><header><h3>{tr('月次進捗の記録','Monthly progress records')}</h3>{#if manage()}<ActionButton label={tr('進捗を記録','Record progress')} disabled={!baseline} onclick={()=>progressEditor()}/>{/if}</header>{#each progress as p}<div class="list-row"><span>{p.month.slice(0,7)} · {tickets.find(t=>t.id===p.ticketId)?.title} · v{p.version}</span><strong>{p.percent}%</strong><p>{p.evidence}</p></div>{/each}</section>
{:else}
<section class="card"><header><h3>{tr('月次確定・訂正版','Monthly confirmation and corrections')}</h3>{#if manage()&&can('projects.evm.confirm')}<ActionButton label={tr('この月を確定','Confirm month')} variant="primary" disabled={busy||calculating||Boolean(previewError)||!preview?.totals} onclick={()=>void confirmReport()}/>{/if}</header><p>{tr('基準計画と対象月に合わせて自動計算します。未解決事項を解消してから確定してください。訂正は新版として保存します。','Values update automatically for the selected baseline and month. Resolve missing information before confirmation. Corrections create a new report version.')}</p>
{#if preview?.unresolved.length}<StatusNotice onDismiss={()=>preview=null} tone="error" message={preview.unresolved.map(unresolvedLabel).join(' / ')}/>{/if}
{#if preview}<div class="table-scroll"><table><thead><tr><th>{tr('作業','Work')}</th><th>BAC</th><th>PV</th><th>{tr('進捗','Progress')}</th><th>AC</th></tr></thead><tbody>{#each preview.rows as r}<tr><th>{r.title}</th><td>{amount(r.budget)}</td><td>{amount(r.planned)}</td><td>{r.progress}%</td><td>{amount(r.actual)}</td></tr>{/each}</tbody></table></div>{/if}
{#each reports.filter(r=>r.month.slice(0,7)===reportMonth) as r}<details class="report"><summary>{r.month.slice(0,7)} · v{r.version} · {r.stale?tr('要再確定','Reconfirmation needed'):tr('確定','Confirmed')} · {tr('基準計画','Baseline')} v{r.snapshot.baselineVersion}</summary><div class="indices">{#each ['bac','pv','ev','ac','cv','sv'] as k}<div><strong>{k.toUpperCase()}</strong><span>{amount(r.snapshot.totals?.[k as keyof Totals])}</span></div>{/each}</div><div class="table-scroll"><table><tbody>{#each r.snapshot.rows as row}<tr><th>{row.title}</th><td>{row.progress}%</td><td>{amount(row.actual)}</td></tr>{/each}</tbody></table></div></details>{/each}
</section>{/if}{/if}{/if}</div>
{#if editor}<ManagementForm title={editor.title} fields={editor.fields} onSave={editor.save} onClose={()=>editor=null}/>{/if}
{#if baselineOpen}<DetailModal title={tr('基準計画・月別予算','Baseline and monthly budgets')} titleId="baseline-editor-title" closeLabel={tr('閉じる','Close')} onClose={()=>{if(!busy&&confirm(tr('入力を破棄しますか？','Discard this draft?')))baselineOpen=false;}}>
{#if baselineError}<StatusNotice onDismiss={()=>baselineError=''} tone="error" message={baselineError}/>{/if}<FormSection title={tr('計画','Plan')} framed columns={2}><FormInput label={tr('名称','Name')} field="baseline-title" value={baselineTitle} required onValueChange={v=>baselineTitle=v}/><SearchSelect label={tr('保存状態','Save as')} field="baseline-state" value={baselineState} options={[{value:'draft',label:tr('下書き','Draft')},...(can('projects.baselines.confirm')?[{value:'confirmed',label:tr('確定','Confirmed')}]:[])]} onSelect={v=>baselineState=v}/><div class="wide"><FormTextarea label={tr('新規・改訂の理由','Creation / revision reason')} field="baseline-reason" value={baselineReason} required onValueChange={v=>baselineReason=v}/><SearchMultiSelect label={tr('予算を配賦する作業（親子の重複は不可）','Budget work packages (no ancestor/descendant overlap)')} field="baseline-work" values={workIds} options={optTickets()} onChange={v=>workIds=v}/></div></FormSection>
<div class="actions"><ActionButton label={tr('配賦月を追加','Add allocation month')} disabled={months.length>=120} onclick={appendMonth}/><span>{settings?.currency} · {tr('税抜','Tax exclusive')}</span></div>
{#each workIds as id}<FormSection title={tickets.find(t=>String(t.id)===id)?.title??id} framed columns={2}><FormInput label={tr('作業の総予算','Work-package budget')} field={'budget-'+id} type="number" value={budgets[id]??'0'} onValueChange={v=>budgets[id]=v}/>{#each months as m}<FormInput label={m} field={'allocation-'+id+'-'+m} type="number" value={allocations[id+':'+m]??'0'} onValueChange={v=>allocations[id+':'+m]=v}/>{/each}</FormSection>{/each}
{#snippet actions()}<ActionButton label={tr('保存','Save')} variant="primary" disabled={busy||!workIds.length} onclick={()=>void saveBaseline()}/>{/snippet}</DetailModal>{/if}
<style>
